function setAudioPath(object,path,value){if(path.startsWith('dialogue.')){if(!object.dialogue.length)object.dialogue.push({speakerName:'',speakerId:'',voiceProfileId:'',voiceProfile:'',text:'',emotion:'',delivery:''});object.dialogue[0][path.split('.')[1]]=value;return}const parts=path.split('.');let target=object;for(const part of parts.slice(0,-1))target=target[part]||(target[part]={});target[parts.at(-1)]=value}
function bindScenes(){$$('[data-field]').forEach(el=>el.addEventListener('input',()=>{const i=Number(el.closest('[data-scene]').dataset.scene),s=current.data.scenes[i],key=el.dataset.field;s[key]=el.value;if(key==='purpose')s.narrativePurpose=el.value;if(key==='visual')s.visualDescription=el.value;if(key==='duration'){const summary=$('#duration-summary');if(summary){const plan=durationPlan(current.data);summary.textContent=durationSummaryText(plan);summary.classList.toggle('notice',!!plan.warning)}}scheduleSave()}));$$('[data-audio-required]').forEach(el=>el.onchange=()=>{const s=current.data.scenes[Number(el.closest('[data-scene]').dataset.scene)];normalizeSceneAudio(s).required=el.checked;updateSceneChecklist(current.data,`scene-${s.id}-audio`,false);scheduleSave()});$$('[data-audio],[data-audio-list]').forEach(el=>el.addEventListener('input',()=>{const s=current.data.scenes[Number(el.closest('[data-scene]').dataset.scene)],a=normalizeSceneAudio(s);if(el.hasAttribute('data-audio-list'))a[el.dataset.audioList]=el.value.split(/\n+/).map(x=>x.trim()).filter(Boolean);else setAudioPath(a,el.dataset.audio,el.value);a.required=true;s.dialogue=a.dialogue.map(x=>x.text).filter(Boolean).join('\n');s.audio={voiceover:a.voiceover.text,music:a.music.description,effects:a.soundEffects};const estimate=audioSpeechEstimate(s),note=el.closest('[data-scene]').querySelector('[data-audio-estimate]');note.textContent=`Perkiraan ucapan: ${estimate.speechSeconds} detik${estimate.overLimit?' — kemungkinan melebihi durasi klip.':''} (perkiraan kasar).`;scheduleSave()}));$$('[data-asset-link]').forEach(el=>el.onchange=()=>{const s=current.data.scenes[Number(el.closest('[data-scene]').dataset.scene)];s.assetIds=s.assetIds||s.referenceAssetIds||[];s.assetIds=el.checked?[...new Set([...s.assetIds,el.dataset.assetLink])]:s.assetIds.filter(id=>id!==el.dataset.assetLink);s.referenceAssetIds=s.assetIds;scheduleSave()});$$('[data-delete-scene]').forEach(el=>el.onclick=()=>{current.data.scenes.splice(Number(el.dataset.deleteScene),1);scheduleSave(true);renderTab()});$$('[data-move]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.index),j=el.dataset.move==='up'?i-1:i+1;[current.data.scenes[i],current.data.scenes[j]]=[current.data.scenes[j],current.data.scenes[i]];scheduleSave(true);renderTab()});$('#add-scene').onclick=()=>{current.data.scenes.push({...sceneDefaults,id:crypto.randomUUID()});scheduleSave(true);renderTab()};$('#to-assets').onclick=()=>setTab('assets')}
function setTab(tab){activeTab=tab;renderProject();window.scrollTo(0,0)}
function effectiveScene(s){return{...s,narrativePurpose:s.narrativePurpose??s.purpose??'',visualDescription:s.visualDescription??s.visual??'',referenceAssetIds:Array.isArray(s.referenceAssetIds)?s.referenceAssetIds:Array.isArray(s.assetIds)?s.assetIds:[],camera:String(s.camera||'').trim()||'medium shot, gerakan kamera lembut',lighting:String(s.lighting||'').trim()||'pencahayaan lembut sesuai suasana adegan',audio:s.audio&&typeof s.audio==='object'?s.audio:{voiceover:'',music:'',effects:[]},continuityIn:s.continuityIn&&typeof s.continuityIn==='object'?s.continuityIn:{},continuityOut:s.continuityOut&&typeof s.continuityOut==='object'?s.continuityOut:{}}}
function buildSceneProduction(project,platform,sourceScene,selectedAssets){const d=normalizeProductionData(project?.data||{},project),scene=sourceScene?effectiveScene(sourceScene):null,ids=scene?(scene.referenceAssetIds||scene.assetIds||[]):[],assets=selectedAssets||ids.map(id=>d.assets.find(a=>a.id===id)).filter(Boolean),byIds=(items,keys)=>(keys||[]).map(id=>items.find(item=>item.id===id)).filter(Boolean),characters=scene?byIds(d.entities.characters,scene.characterIds):[],products=scene?byIds(d.entities.products,scene.productIds):[],location=scene?(d.entities.locations.find(item=>item.id===scene.locationId)||null):null;return{schemaVersion:d.schemaVersion,project:project?.title||'',platform:platform.name,projectBrief:{...d.projectBrief},storyPlan:{...d.storyPlan},productionSettings:{...d.productionSettings,platform:project?.platform||d.productionSettings.platform},scene,characters,products,location,selectedAssets:assets,durationSummary:durationPlan(d),continuity:scene?{input:scene.continuityIn,output:scene.continuityOut}:null,audioDirector:d.audioDirector,audioEstimate:scene?audioSpeechEstimate(scene):null}}
function promptExport(project,platform,scene,selectedAssets,promptText){const pack=buildSceneProduction(project,platform,scene,selectedAssets);if(promptText!==undefined)pack.prompt=promptText;return pack}
function makePrompt(s,plat,d,project=current){const source=project||{title:'',platform:d.productionSettings?.platform||'flow',data:d},pack=buildSceneProduction(source,plat,s),scene=pack.scene,brief=pack.projectBrief,story=pack.storyPlan;const describe=items=>items.map(item=>[item.name,item.description,item.identity,item.appearance].filter(Boolean).join(': ')).filter(Boolean).join('; '),storyGuide=[story.title,story.logline,story.opening,story.conflict,story.development,story.ending].filter(Boolean).join(' → ');const parts=[plat.prompt,storyGuide?`Rencana cerita: ${storyGuide}.`:'',`Panduan cerita: gaya ${brief.visualStyle||'natural'}.`,brief.characterNotes?`Konsistensi karakter: ${brief.characterNotes}`:'',brief.locationNotes&&!uniqueText([scene.location,scene.time,pack.location?.name]).some(value=>value.toLocaleLowerCase()===String(brief.locationNotes).trim().toLocaleLowerCase())?`Konsistensi dunia/lokasi: ${brief.locationNotes}`:'',brief.keyMessage?`Pesan cerita: ${brief.keyMessage}`:'',pack.characters.length?`Karakter yang harus dipertahankan: ${describe(pack.characters)}.`:'',pack.products.length?`Produk yang harus dipertahankan: ${describe(pack.products)}.`:'',pack.location&&!(String(scene.location||'').trim().toLocaleLowerCase()===String(pack.location.name||'').trim().toLocaleLowerCase()&&![pack.location.description,pack.location.identity,pack.location.appearance].some(Boolean))?`Lokasi yang harus dipertahankan: ${describe([pack.location])}.`:'',`Adegan: ${scene.title||'Momen cerita'}.`,scene.narrativePurpose?`Tujuan: ${scene.narrativePurpose}`:'',scene.visualDescription?`Visual: ${scene.visualDescription}`:'',`Lokasi dan waktu: ${uniqueText([scene.location,scene.time,pack.location?.name]).join(', ')||brief.locationNotes||'sesuai kebutuhan cerita'}.`,`Aksi: ${scene.action||'aksi karakter utama'}.`,scene.expression?`Ekspresi: ${scene.expression}`:'',`Framing dan kamera: ${scene.camera}.`,`Pencahayaan: ${scene.lighting}.`,`Dialog/narasi: ${scene.audioPlan?.dialogue?.map(x=>x.text).filter(Boolean).join(' / ')||'tanpa dialog'}.`,`Durasi target klip ini: ${scene.duration||brief.targetDuration||'5 detik'}.`,`Rencana video: target proyek ${pack.durationSummary.projectTarget||'belum ditentukan'}; total durasi scene ${pack.durationSummary.sceneTotalSeconds===null?'belum lengkap':`${pack.durationSummary.sceneTotalSeconds} detik`}.${pack.durationSummary.warning?` ${pack.durationSummary.warning}`:''}`,'Batas durasi per klip bergantung pada model video yang dipilih di platform.',audioPromptLines(pack),pack.selectedAssets.length?`Aset referensi yang perlu diunggah secara manual: ${pack.selectedAssets.map(a=>`${a.name} (${a.type||a.category||'referensi'})`).join('; ')}.`:'Belum ada aset yang ditautkan ke adegan ini.'];return parts.filter(Boolean).map(cleanPromptText).join('\n\n')}
function estimateSpeechSeconds(text){const words=String(text||'').trim().split(/\s+/).filter(Boolean).length;return words?Math.ceil(words/2.5):0}
function audioSpeechEstimate(scene){const a=normalizeSceneAudio(scene),words=[...a.dialogue.map(x=>x.text),a.voiceover.text].filter(Boolean).join(' '),speechSeconds=estimateSpeechSeconds(words),clipSeconds=durationSeconds(scene.duration);return{speechSeconds,clipSeconds,overLimit:clipSeconds!==null&&speechSeconds>clipSeconds}}
function audioPromptLines(pack){const s=pack.scene,a=s.audioPlan||{},lines=[],estimate=audioSpeechEstimate(s);if(!a.required)return 'Rencana audio: tidak diperlukan untuk adegan ini.';lines.push('Rencana audio untuk produksi manual; audio belum dibuat dan lip-sync tidak dijamin.');for(const d of a.dialogue||[])if(d.text)lines.push(`Dialog karakter ${d.speakerName||d.speakerId||'pembicara belum ditentukan'}: “${d.text}”. Profil suara tetap: ${d.voiceProfileId||'ID belum ditentukan'}${d.voiceProfile?` (${d.voiceProfile})`:''}; emosi ${d.emotion||'natural'}; penyampaian ${d.delivery||'natural'}.`);if(a.voiceover?.text)lines.push(`Voice-over/narasi oleh ${a.voiceover.narratorName||a.voiceover.narratorId||'narator belum ditentukan'}: “${a.voiceover.text}”. Profil suara tetap: ${a.voiceover.voiceProfileId||'ID belum ditentukan'}${a.voiceover.voiceProfile?` (${a.voiceover.voiceProfile})`:''}; emosi ${a.voiceover.emotion||'natural'}; penyampaian ${a.voiceover.delivery||'natural'}.`);if(a.ambience?.length)lines.push(`Suasana latar: ${a.ambience.join(', ')}.`);if(a.soundEffects?.length)lines.push(`Efek suara: ${a.soundEffects.join(', ')}.`);if(a.music?.description)lines.push(`Musik: ${a.music.description}; mood ${a.music.mood||'belum ditentukan'}; transisi ${a.music.transition||'sesuai kebutuhan'}.`);if(a.music?.continuityId)lines.push(`ID kesinambungan musik: ${a.music.continuityId}.`);if(pack.audioDirector?.continuityNotes)lines.push(`Konsistensi audio antarscene: ${pack.audioDirector.continuityNotes}`);lines.push(`Perkiraan dialog/narasi ${estimate.speechSeconds} detik pada klip ${estimate.clipSeconds??'durasi belum diketahui'} detik${estimate.overLimit?' — teks kemungkinan terlalu panjang, ringkas atau ubah durasi':''}.`);return lines.join(' ')}
function durationSeconds(value){const match=String(value||'').trim().toLowerCase().match(/^(\d+(?:[.,]\d+)?)\s*(detik|det|s|sec|seconds?|menit|mnt|min|minutes?)?$/);if(!match)return null;const amount=Number(match[1].replace(',','.'));if(!Number.isFinite(amount)||amount<=0)return null;return Math.round(amount*(['menit','mnt','min','minute','minutes'].includes(match[2])?60:1))}
function durationPlan(data){const target=data.projectBrief?.targetDuration||data.duration||'',targetSeconds=durationSeconds(target),sceneDurations=(data.scenes||[]).map(scene=>durationSeconds(scene.duration)),known=sceneDurations.filter(value=>value!==null),totalSeconds=known.reduce((sum,value)=>sum+value,0),complete=known.length===sceneDurations.length;return{projectTarget:target,targetSeconds,sceneCount:sceneDurations.length,sceneTotalSeconds:complete?totalSeconds:null,knownSceneSeconds:totalSeconds,allSceneDurationsKnown:complete,matches:targetSeconds!==null&&complete&&targetSeconds===totalSeconds,providerClipLimitSeconds:null,warning:targetSeconds===null?'':!complete?'Isi durasi setiap adegan agar total dapat dibandingkan dengan target proyek.':targetSeconds!==totalSeconds?`Total adegan ${totalSeconds} detik berbeda dari target proyek ${targetSeconds} detik.`:''}}
function durationSummaryText(plan){return `Target proyek: ${plan.projectTarget||'belum ditentukan'} · total scene: ${plan.sceneTotalSeconds===null?'belum lengkap':`${plan.sceneTotalSeconds} detik`}${plan.warning?` · ${plan.warning}`:''}`}
function uniqueText(values){const seen=new Set();return values.map(value=>String(value||'').trim()).filter(value=>{const key=value.toLocaleLowerCase();if(!key||seen.has(key))return false;seen.add(key);return true})}
function cleanPromptText(value){return String(value||'').replace(/\.{2,}/g,'.').replace(/[ \t]+([,.!?;:])/g,'$1').trim()}
function linkAssetToScenes(data,assetId,sceneIds){const selected=new Set(sceneIds);for(const scene of data.scenes||[]){const ids=new Set(Array.isArray(scene.referenceAssetIds)?scene.referenceAssetIds:Array.isArray(scene.assetIds)?scene.assetIds:[]);if(selected.has(scene.id))ids.add(assetId);else ids.delete(assetId);scene.assetIds=[...ids];scene.referenceAssetIds=scene.assetIds}return data}
function removeAssetReferences(data,assetId){data.assets=(data.assets||[]).filter(asset=>asset.id!==assetId);for(const scene of data.scenes||[]){const linked=(scene.assetIds||scene.referenceAssetIds||[]).includes(assetId);scene.assetIds=(scene.assetIds||scene.referenceAssetIds||[]).filter(id=>id!==assetId);scene.referenceAssetIds=scene.assetIds;if(linked){scene.productionChecklist=scene.productionChecklist||{};scene.productionChecklist.assets=scene.assetIds.length>0;if(data.checks)data.checks[`scene-${scene.id}-assets`]=scene.productionChecklist.assets;const c=scene.productionChecklist;scene.productionStatus=c.collected?'collected':c.generated?'in_progress':c.prompt?'prompt_ready':c.assets?'references_ready':'Draft';scene.production=scene.productionStatus}}return data}
function updateSceneChecklist(data,checkId,checked){const [sceneKey,key]=checkId.split(/-(?=[^-]+$)/);data.checks=data.checks||{};data.checks[checkId]=!!checked;const scene=(data.scenes||[]).find(item=>`scene-${item.id}`===sceneKey);if(!scene)return null;scene.productionChecklist=scene.productionChecklist||{};scene.productionChecklist[key]=!!checked;const c=scene.productionChecklist;scene.productionStatus=c.collected?'collected':c.generated?'in_progress':c.prompt?'prompt_ready':c.assets?'references_ready':'Draft';scene.production=scene.productionStatus;return scene}
function manualScenes(idea,duration){const chunks=idea.split(/(?<=[.!?])\s+|\n+/).map(x=>x.trim()).filter(Boolean);const lines=(chunks.length>1?chunks:idea.split(/,\s*| lalu | kemudian /i)).map(x=>x.trim()).filter(Boolean).slice(0,5);const titles=['Pembuka','Perkembangan','Penutup'];const scenes=lines.map((line,i)=>({...sceneDefaults,id:crypto.randomUUID(),title:titles[i]||`Momen ${i+1}`,purpose:i===0?'Perkenalkan tokoh dan situasi':i===lines.length-1?'Tutup dengan perubahan atau kesan':'Majukan kejadian cerita',visual:line,action:line.charAt(0).toUpperCase()+line.slice(1),camera:'Medium shot; gerakan lembut mengikuti aksi',duration:duration==='30 detik'?'4 detik':'5 detik'}));if(scenes.length===1)scenes.push({...sceneDefaults,id:crypto.randomUUID(),title:'Momen lanjutan',purpose:'Tunjukkan respons atau perubahan',action:'Tunjukkan respons tokoh terhadap kejadian sebelumnya.',camera:'Close-up ekspresi, gerakan perlahan'});if(scenes.length)scenes.push({...sceneDefaults,id:crypto.randomUUID(),title:'Penutup',purpose:'Berikan penutup yang terasa utuh',action:'Tampilkan hasil atau perasaan setelah kejadian.'});return scenes}
async function draftStory(){const idea=$('#idea-input').value.trim();if(!idea){toast('Tulis ide singkat dulu, ya.');$('#idea-input').focus();return}if(current.data.scenes.length&&!confirm('Storyboard yang ada akan diganti dengan kerangka manual. Lanjutkan?'))return;current.idea=idea;current.data.duration=$('#duration-input').value;current.data.style=$('#style-input').value;current.data.scenes=manualScenes(idea,current.data.duration);current.status='Storyboard siap';if(await saveNow())setTab('storyboard');else pendingAdvance='storyboard'}
async function checkAI(){const status=$('#ai-status'),select=$('#ai-model'),button=$('#ai-story');if(!status)return;status.textContent='Memeriksa layanan Ollama di komputer ini…';button.disabled=true;select.disabled=true;try{const res=await api('/api/ai/status');select.innerHTML=res.models?.length?res.models.map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join(''):'<option value="">Tidak ada model terpasang</option>';select.disabled=!res.models?.length;button.disabled=!res.models?.length;status.textContent=res.models?.length?'Ollama tersedia. Draft hanya dibuat setelah Anda menekan tombol AI.':'Ollama tidak terdeteksi atau belum memiliki model. AI lokal belum siap.'}catch{select.innerHTML='<option>Tidak dapat memeriksa</option>';status.textContent='Status Ollama tidak dapat diperiksa.'}}
async function requestAIDraft(){const idea=$('#idea-input').value.trim();if(!idea){toast('Tulis ide singkat dulu, ya.');$('#idea-input').focus();return}const button=$('#ai-story');button.disabled=true;button.textContent='Menyusun alternatif…';try{const result=await api('/api/ai/story',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idea,goal:current.goal,duration:$('#duration-input').value,style:$('#style-input').value,model:$('#ai-model').value})});aiDraft=result.draft;renderAIReview()}catch(e){toast(e.message);checkAI()}finally{if($('#ai-story')){$('#ai-story').disabled=false;$('#ai-story').innerHTML='Buat alternatif cerita dengan AI lokal <span>✦</span>'}}}
function renderAIReview(){const d=aiDraft,box=$('#ai-options');box.innerHTML=(d.alternatives||[]).map((a,i)=>`<label class="ai-option"><input type="radio" name="ai-option" value="${i}" ${i===0?'checked':''}><span><b>${esc(a.title||`Alternatif ${i+1}`)}</b><small>${esc(a.logline||a.concept||'')}</small><small>${(a.scenes||[]).length} adegan · ${(a.characters||[]).length} tokoh · ${(a.locations||[]).length} lokasi</small><small>${esc([a.opening,a.conflict,a.development,a.ending].filter(Boolean).join(' → '))}</small></span></label>`).join('');$('#ai-review-dialog').showModal()}
$('#apply-ai-draft').onclick=async()=>{if(!aiDraft)return;const index=Number($('input[name="ai-option"]:checked')?.value||0),a=aiDraft.alternatives[index];if(current.data.scenes.length&&!confirm('Menerapkan cerita ini akan mengganti storyboard. Aset dan catatan proyek tetap tersimpan. Lanjutkan?'))return;current.idea=$('#idea-input').value.trim();current.data.duration=$('#duration-input').value;current.data.style=$('#style-input').value;current.data.message=a.message||current.data.message||'';current.data.story={title:a.title||'',logline:a.logline||'',concept:a.concept||'',opening:a.opening||'',conflict:a.conflict||'',development:a.development||'',ending:a.ending||'',audience:a.audience||''};current.data.storyPlan={...current.data.story,approvalStatus:'draft'};current.data.characters=a.characters||[];current.data.locations=a.locations||[];current.data.entities.characters=current.data.characters;current.data.entities.locations=current.data.locations;current.data.scenes=a.scenes||[];current.status='Storyboard siap';closeAIAfterSave=true;if(await saveNow()){pendingAdvance='storyboard';const destination=pendingAdvance;pendingAdvance=null;setTab(destination);finishAIApply()}else{pendingAdvance='storyboard'}};
function finishAIApply(){if(closeAIAfterSave){closeAIAfterSave=false;$('#ai-review-dialog').close();toast('Draft AI lokal diterapkan. Periksa dan sunting adegannya.')}}
function syncProjectData(project){if(!project)return;const d=normalizeProductionData(project.data,project);project.data=d;d.projectBrief.idea=project.idea||'';d.projectBrief.videoType=project.goal||'';d.projectBrief.keyMessage=d.message||d.projectBrief.keyMessage||'';d.projectBrief.visualStyle=d.style||d.projectBrief.visualStyle||'';d.projectBrief.targetDuration=d.duration||d.projectBrief.targetDuration||'';d.projectBrief.characterNotes=d.character||d.projectBrief.characterNotes||'';d.projectBrief.locationNotes=d.world||d.projectBrief.locationNotes||'';d.productionSettings.platform=project.platform||d.productionSettings.platform||'flow';for(const s of d.scenes){s.narrativePurpose=s.purpose??s.narrativePurpose??'';s.visualDescription=s.visual??s.visualDescription??'';s.referenceAssetIds=Array.isArray(s.assetIds)?s.assetIds:Array.isArray(s.referenceAssetIds)?s.referenceAssetIds:[];s.assetIds=s.referenceAssetIds}return d}
function scheduleSave(){if(!current)return;syncProjectData(current);clearTimeout(saveTimer);saveRevision++;pendingSave=current;setSaveState('Menyimpan…',current.id);saveTimer=setTimeout(()=>saveNow(pendingSave?.id===current.id?pendingSave:current),450);try{sessionStorage.setItem(`ai-video-studio:unsaved:${current.id}`,JSON.stringify(current))}catch{}}
function setSaveState(message,projectId=current?.id){if(!projectId)return;saveMessages.set(projectId,message);if(current?.id===projectId){const el=$('#save-state');if(el)el.textContent=message}}
function backupDraft(candidate,snapshot){try{sessionStorage.setItem(`ai-video-studio:unsaved:${candidate.id}`,snapshot);return true}catch{return false}}
async function saveNow(candidate=pendingSave||current){if(assetUploadInProgress)await assetUploadBarrier;if(!candidate)return false;syncProjectData(candidate);clearTimeout(saveTimer);saveTimer=null;const revision=++saveRevision,snapshot=JSON.stringify(candidate),key=`ai-video-studio:unsaved:${candidate.id}`;pendingSave=candidate;setSaveState('Menyimpan…',candidate.id);backupDraft(candidate,snapshot);const request=saveQueue.catch(()=>{}).then(()=>api('/api/projects/'+candidate.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot}));saveQueue=request.then(()=>undefined,()=>undefined);let saved;try{saved=await request}catch(e){if(revision!==saveRevision)return false;pendingSave=candidate;const backedUp=backupDraft(candidate,snapshot);setSaveState(backedUp?'Belum tersimpan — draft sementara ada di tab ini':'Belum tersimpan — draft hanya ada di memori tab ini; jangan tutup tab',candidate.id);toast(`Penyimpanan gagal: ${e.message}`);return false}if(revision!==saveRevision||pendingSave!==candidate)return false;if(current?.id===candidate.id)current=saved;try{sessionStorage.removeItem(key)}catch{}pendingSave=null;const i=projects.findIndex(p=>p.id===saved.id);if(i>=0)projects[i]=saved;else projects.unshift(saved);$('#project-count').textContent=projects.length;renderCards();setSaveState('Perubahan tersimpan',saved.id);if(pendingAdvance){const destination=pendingAdvance;pendingAdvance=null;setTab(destination);finishAIApply()}return true}
async function saveBeforeLeaving(){if(!current)return true;const id=current.id;if(!pendingSave&&(!saveMessages.has(id)||saveMessages.get(id)==='Perubahan tersimpan'))return true;clearTimeout(saveTimer);saveTimer=null;return await saveNow(pendingSave?.id===id?pendingSave:current)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Tersalin ke clipboard.')}catch{toast('Clipboard tidak tersedia. Pilih lalu salin teks secara manual.')}}
function mergeAsset(project,asset){if(!project)return;const data=project.data&&typeof project.data==='object'?project.data:(project.data={});data.assets=Array.isArray(data.assets)?data.assets:[];if(!data.assets.some(item=>item.id===asset.id||item.url===asset.url))data.assets.push(asset)}
async function uploadAssets(e){if(!current)return;const projectId=current.id,category=$('#asset-type').value,initialCurrent=current,initialPending=pendingSave?.id===projectId?pendingSave:null;let failed=0;assetUploadInProgress=true;let releaseUpload;assetUploadBarrier=new Promise(resolve=>{releaseUpload=resolve});clearTimeout(saveTimer);saveTimer=null;await saveQueue.catch(()=>{});try{for(const file of e.target.files){try{const result=await api(`/api/projects/${projectId}/assets`,{method:'POST',headers:{'Content-Type':file.type,'X-Filename':file.name,'X-Asset-Type':category},body:file});const asset=result.asset||{id:result.id||result.url,name:result.name||file.name,url:result.url,type:category};const targets=[initialCurrent,initialPending,current?.id===projectId?current:null,pendingSave?.id===projectId?pendingSave:null,projects.find(p=>p.id===projectId)];for(const target of targets)mergeAsset(target,asset);if(pendingSave?.id===projectId){saveRevision++;const backedUp=backupDraft(pendingSave,JSON.stringify(pendingSave));if(!backedUp&&saveMessages.get(projectId)?.startsWith('Belum tersimpan'))setSaveState('Belum tersimpan — draft hanya ada di memori tab ini; jangan tutup tab',projectId)}}catch(err){failed++;toast(`${file.name}: ${err.message}`)}}}finally{assetUploadInProgress=false;releaseUpload();if(pendingSave?.id===projectId&&saveMessages.get(projectId)==='Menyimpan…')scheduleSave()}if(current?.id===projectId)renderTab();if(!failed)toast('Gambar referensi tersimpan di komputer ini.')}
function showCreate(){$('#create-form').reset();$('#create-dialog').showModal()}
$('#new-project').onclick=$('#side-new').onclick=$('#empty-new').onclick=$('#projects-new').onclick=showCreate;
$('#help-button').onclick=()=>$('#help-dialog').showModal();
$('#create-form').onsubmit=async e=>{e.preventDefault();if(!await saveBeforeLeaving())return;const body={title:$('#new-title').value.trim()||'Proyek baru',goal:$('#new-goal').value,idea:$('#new-idea').value.trim(),platform:'flow'};try{const p=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#create-dialog').close();await load();openProject(p.id)}catch(err){toast(err.message)}};
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){pendingAdvance=null;setTab(tab.dataset.tab);return}const view=e.target.closest('[data-view]');if(view){if(!await saveBeforeLeaving())return;navigate(view.dataset.view);return}const open=e.target.closest('[data-open]');if(open){if(!await saveBeforeLeaving())return;openProject(open.dataset.open);return}if(e.target.dataset?.linkAll){linkAssetToScenes(ensureData(),e.target.dataset.linkAll,ensureData().scenes.map(scene=>scene.id));scheduleSave();renderTab();toast('Aset ditautkan ke semua adegan.');return}if(e.target.dataset?.deleteAsset){const asset=ensureData().assets.find(item=>item.id===e.target.dataset.deleteAsset);if(!asset)return;const impacted=ensureData().scenes.filter(scene=>(scene.referenceAssetIds||scene.assetIds||[]).includes(asset.id));const detail=impacted.length?`Aset ini digunakan oleh: ${impacted.map(scene=>scene.title||'Adegan tanpa judul').join(', ')}. Referensi akan dilepas.`:'Aset ini belum digunakan oleh adegan.';if(!confirm(`Hapus aset “${asset.name}”? ${detail}`))return;if(!await saveBeforeLeaving())return;try{const result=await api(`/api/projects/${current.id}/assets/${asset.id}`,{method:'DELETE'});current=result.project||current;if(!result.project)removeAssetReferences(ensureData(),asset.id);const index=projects.findIndex(item=>item.id===current.id);if(index>=0)projects[index]=current;saveMessages.set(current.id,'Perubahan tersimpan');renderCards();renderTab();toast('Aset dihapus dan referensi adegan diperbarui.')}catch(error){toast(`Aset belum dihapus: ${error.message}`)}return}if(e.target.id==='retry-save'){if(await saveNow(pendingSave||current))renderProject();return}if(e.target.id==='rename-project'){const name=prompt('Nama proyek',current.title);if(name?.trim()){current.title=name.trim().slice(0,80);if(await saveNow())renderProject()}}if(e.target.id==='delete-project'&&confirm(`Hapus proyek “${current.title}” beserta gambar yang diunggah?`)){if(!await saveBeforeLeaving())return;await api('/api/projects/'+current.id,{method:'DELETE'});current=null;await load();navigate('projects');toast('Proyek dihapus.')}});
load().catch(()=>toast('Tidak dapat memuat proyek. Coba muat ulang halaman.'));
